result:
   .userInfor{
       padding: 14px 10px;
	   .list{
		   margin-top: 16px;
		   padding-top: 16px;
		   border-top:1px solid #eee;
		   .item{
			   font-size: 13px;
			   color: #999;
			   .num{
				   font-size: 14px;
				   font-weight: 600;
				   color: #333333;
				   margin-left: 4px;
			   }
		   }
	   }
       .right{
		   &.on{
			   .item{
				   color: #666666;
			   }
		   }
           .item{
               text-align: center;
               font-weight: 400;
               color: #999;
               font-size: 11px;
               margin-left: 16px;
               .num{
                   font-size: 16px;
                   margin-bottom: 2px;
				   font-weight: 600;
				   color: #333333;
               }
           }
           .iconfont{
               font-weight: 400;
               //color: #333333;
               font-size: 15px;
               margin-bottom: 2px;
           }
       }
       .left{
           .pictrue{
               width: 45px;
               height: 45px;
               border-radius: 50%;
               margin-right: 10px;
			   img {
				   border-radius: 50%;
				   width: 100%;
				   height: 100%;
				   object-fit: cover;
			   }
               .empty-box{
                   border-radius: 50%;
				   background-color: #F3F9FF;
				   border: 1px solid #EEEEEE;
                   .iconfont-diy{
                       font-size: 20px;
                   }
				   img {
					   width: 26px;
					   height: 20px;
				   }
               }
           }
           .text{
               font-weight: 400;
               color: #333333;
               font-size: 16px;
			   .name{
				   img{
					   width: 38px;
					   height: 16px;
					   margin-left: 5px;
				   }
			   }
               .progress{
                   overflow: hidden;
                   background-color: #EEEEEE;
                   width: 60px;
                   height: 7px;
                   border-radius: 3px;
                   position: relative;
                   .bgReds{
                       width: 80%;
                       height: 100%;
                       transition: width 0.6s ease;
					   border-radius: 3px;
                   }
               }
			   .percent{
				   font-size: 10px;
				   margin-left: 4px;
			   }
               .phone{
                   font-weight: 400;
                   //color: #333;
                   font-size: 10px;
                   margin-top: 3px;
                   .iconshouji{
                       margin-right: 2px;
                       font-size: 12px;
                   }
               }
           }
       }
   }
